//百蛊啖魂1126
class Skill1126Stub extends HSkillStubBase {
    constructor() {
        super(1126);
    }
    attach() {
        this.hookGetCooldownTimeAfter((ret, stub, skill) => {
            return 7000;
        });
        this.hookStateGetTimeSimple([300, 200]);
        this.hookStateAttackReplace((stub, skill) => {
            const hSkill = new HSkill(skill);
            const hPlayer = new HPlayerWrapper(hSkill);

            // 计算概率
            let prob = hSkill.GetT3() * 0.1 + 1.0;
            let probMod = hSkill.GetT4() * 0.03;
            prob = (1.0 - hPlayer.GetLevel() * 0.002 + probMod) * 100.0 * prob;

            hPlayer.SetProbability(prob);

            // 设置时间
            let time = -2000 * hSkill.GetT3() + 48000;
            hPlayer.SetTime(time);
            hPlayer.SetBuffid(1);

            // 计算伤害
            let hp = hPlayer.GetHp();
            let level = hSkill.GetLevel();
            let damage = hSkill.GetT1() * 0.005 * level * hp;
            let damageMod = hSkill.GetT1() * 0.1 + 1.0;
            let damageBase = level * 371.84;
            damage = ((level * 8.96 * level + damageBase + 8320.0) * damageMod + damage);
            hPlayer.SetAmount(damage);

            hPlayer.SetValue(0.0);
            hPlayer.SetHpleak(1);

            // 禁食效果
            let dietProb = 3 * hSkill.GetT0() + 3 * hSkill.GetLevel();
            hPlayer.SetProbability(dietProb);
            // console.log(dietProb);
            let dietTime = 1000 * hSkill.GetT2() + 4100;
            hPlayer.SetTime(dietTime);
            hPlayer.SetDiet(1);

            // 随机效果
            let rand = Math.floor(Math.random() * 100);
            let wrapProb = 600 * (rand / 67);
            hPlayer.SetProbability(wrapProb);

            let wrapTime = 2050 * hSkill.GetT2();
            hPlayer.SetTime(wrapTime);
            hPlayer.SetWrap(1);

            // 固定效果
            hPlayer.SetProbability(120.0);
            hPlayer.SetTime(10000.0);
            hPlayer.SetRatio(0.2);

            // 清除血槽
            let var1 = hPlayer.GetVar1();
            let skillRate = hPlayer.GetSkillrate();
            let skillAttackEn = hPlayer.GetSkillAttackEn();

            if (var1 > skillRate + skillAttackEn) {
                hPlayer.SetAmount(1);
            } else {
                hPlayer.SetAmount(0);
            }

            hPlayer.SetAbolishbloodpool(1);

            return 1;
        });
    }
}
new Skill1126Stub().attach();

