"use script"
const HSkillStubBase = __webpack_require__(9262);
const HSkill = __webpack_require__(1131);
const HPlayerWrapper = __webpack_require__(3282);
const HGPlayer = __webpack_require__(1222);
const BaseHookSkillStub = __webpack_require__(9571);
const { HookModuleBase } = __webpack_require__(8252);
const {
  occuMap,
  // 彰武
  ZhangWuList, ZhangWuMaoList, ZhangWuYiFuList, ZhangWuXieList, ZhangWuYaDaiList,
  // 混虚
  HunXuList, HunXuMaoList, HunXuYiFuList, HunXuXieList, HunXuYaDaiList,
  // 昭武
  ZhaoWuList, ZhaoWuMaoList, ZhaoWuYiFuList, ZhaoWuXieList, ZhaoWuYaDaiList,
} = __webpack_require__(3093);

// 初始化模块基址
if (typeof Process !== 'undefined' && Process.enumerateModules) {
  try {
    HookModuleBase.initializeModuleBaseIndex(Process.enumerateModules());
  } catch (error) {
    console.error('初始化模块基址失败:', error);
  }
}

// 装备转换
class Equipment extends BaseHookSkillStub {
  constructor() {
    super(1030);
  }

  attach() {
    // 设置冷却时间为0
    this.GetCooldowntime((stub, skill, originFunc) => {
      if (!this.validateSkill(skill)) {
        return originFunc(stub.stubPointer, skill.skillPointer);
      }
      return 0;
    });

    // 装备转换逻辑
    this.getStateAttack((stub, skill, originFunc) => {
      if (!this.validateSkill(skill)) {
        return 0;
      }
      const player = skill.GetPlayer();
      if (!player) return 0;

      try {
        // 获取装备信息
        const gplayer = skill.GetGPlayer();
        const inventory = gplayer.GetInventory();
        const firstItem = inventory.GetItem(0);

        if (!firstItem) {
          console.log('无法获取装备');
          return 0;
        }

        const firstItemId = firstItem.GetType();
        const occu = player.GetOccupation();
        const occuIndex = occuMap.indexOf(Number(occu));
        const isMale = player.GetGender() === 1;

        // 获取新装备ID
        const outputId = this.getNewEquipId(firstItemId, occuIndex, isMale);
        if (!outputId) {
          console.log('该装备无法转换');
          return 0;
        }

        // 执行转换
        try {
          // 写入新ID
          firstItem.pointer.writeInt(outputId);
          console.log(`转换装备: ${firstItemId} -> ${outputId}`);

          // 更新装备数据
          const equipData = Memory.alloc(50);
          inventory.GetItemData(0, equipData);

          // 更新物品
          gplayer.ObtainItem(gplayer.playerPointer, 0, equipData, 0, 0);

          // 恢复原始ID并移除
          firstItem.pointer.writeInt(firstItemId);
          gplayer.TakeOutItem(0, firstItemId, 1);
        } catch (error) {
          console.error('转换失败:', error);
          if (firstItem.pointer) firstItem.pointer.writeInt(firstItemId);
        }

        // 设置20秒无敌状态
        // player.SetInvincible(20000);
      } catch (error) {
        console.error('装备转换错误:', error);
      }
      
      return 0;
    });
  }

  validateSkill(skill) {
    return skill && typeof skill.GetId === 'function' &&
      skill.GetPlayer && typeof skill.GetPlayer === 'function';
  }

  getNewEquipId(equipId, occuIndex, isMale) {
    const equipLists = [
      // 彰武系列
      { list: ZhangWuList, useGender: false },      // 武器
      { list: ZhangWuMaoList, useGender: true },    // 帽子
      { list: ZhangWuYiFuList, useGender: true },   // 衣服
      { list: ZhangWuXieList, useGender: true },    // 鞋子
      { list: ZhangWuYaDaiList, useGender: true },  // 腰带
      // 混虚系列
      { list: HunXuList, useGender: false },        // 武器
      { list: HunXuMaoList, useGender: true },      // 帽子
      { list: HunXuYiFuList, useGender: true },     // 衣服
      { list: HunXuXieList, useGender: true },      // 鞋子
      { list: HunXuYaDaiList, useGender: true },    // 腰带
      // 昭武系列
      { list: ZhaoWuList, useGender: false },       // 武器
      { list: ZhaoWuMaoList, useGender: true },     // 帽子
      { list: ZhaoWuYiFuList, useGender: true },    // 衣服
      { list: ZhaoWuXieList, useGender: true },     // 鞋子
      { list: ZhaoWuYaDaiList, useGender: true },   // 腰带
    ];

    for (const { list, useGender } of equipLists) {
      if (list?.includes(equipId)) {
        return useGender ?
          list[occuIndex * 2 + (isMale ? 0 : 1)] :
          list[occuIndex];
      }
    }
    return null;
  }
}

try {
  const equipment = new Equipment();
  equipment.attach();
  console.log("[+] 在线装备转换已加载");
} catch (error) {
  console.error('装备转换初始化失败:', error);
}

module.exports = Equipment; 

