class Skill1520Stub extends HSkillStubBase {
  constructor() {
    super(1520);
  }
  attach() {
    this.hookTakeEffectReplace((stub, skill) => {
      const hSkill = new HSkill(skill);
      const hPlayer = new HPlayerWrapper(hSkill);

      // 获取技能等级
      const level = hSkill.GetLevel();

      // 计算防御加成
      let defBonus = 10 * level;
      defBonus += level * 0.5 * level;
      hPlayer.SetPasadddefence(defBonus);

      // 计算弱点加成
      let weakBonus = 5 * level;
      hPlayer.SetPasaddweak(weakBonus);

      // 计算暴击加成
      let critBonus = Math.floor(level / 9.5) * 0.0305;
      hPlayer.SetPasinccrit(critBonus);

      // 计算抗性加成
      if (level >= 10) {
        let antiBonus = 2.5 * level;
        hPlayer.SetPasaddanti(antiBonus);
      }

      return 1;
    });
  }
}
new Skill1520Stub().attach();


