const getRandomProp = () => {
    // 计算总权重
    const totalWeight = PropList.reduce((sum, prop) => sum + prop.weight, 0);

    // 生成随机数
    let random = Math.floor(Math.random() * totalWeight);

    // 根据权重选择道具
    for (const prop of PropList) {
        random -= prop.weight;
        if (random < 0) {
            return prop;
        }
    }

    // 保底返回第一个道具
    return PropList[0];
};

module.exports = {
    PropList,
    getRandomProp
};

