let doubleDropTimer = null;
let warningTimer = null;

//开启双倍掉落（全服）7088
class Skill7088Stub extends HSkillStubBase {
    constructor() {
        super(7088);
    }
    attach() {
        this.setType(13)//
        this.setRangeType(5)
        this.hookStateGetTimeSimple([1, 1]);
        this.hookStateAttackReplace((stub, skill) => {
            // console.log("7088");
            const hSkill = new HSkill(skill);
            const hPlayer = new HPlayerWrapper(hSkill);
            let level = hSkill.GetLevel();
            //调用双倍掉落。技能等于1级是开启，等于0级是关闭
            const hGplayer = hSkill.getHGPlayer();
            const playerId = hGplayer.getPlayerID();
            const playerName = hGplayer.getPlayerName();

            // 调用双倍掉落功能
            try {
                // 获取世界参数
                const worldParam = AllNativeFunc.gsHookCall('_ZN7gmatrix13GetWorldParamEv');
                if (worldParam) {
                    // 设置双倍掉落状态
                    worldParam.add(5).writeU8(level);

                    // 发送广播消息
                    const message = level === 1 ? `全服双倍掉落已开启！` : `全服双倍掉落已关闭！`;
                    HGPlayer.broadChatMsg(playerId, message, 14);

                    // 如果是开启双倍掉落，设置计时器
                    if (level === 1) {
                        // 清除可能存在的旧计时器
                        if (doubleDropTimer) {
                            clearTimeout(doubleDropTimer);
                        }
                        if (warningTimer) {
                            clearTimeout(warningTimer);
                        }

                        // 设置1分钟警告
                        warningTimer = setTimeout(() => {
                            HGPlayer.broadChatMsg(playerId, "双倍掉落将在1分钟后结束！", 14);
                        }, 59 * 60 * 1000); // 59分钟后发出警告

                        // 设置60分钟后关闭
                        doubleDropTimer = setTimeout(() => {
                            try {
                                // 关闭双倍掉落
                                worldParam.add(5).writeU8(0);
                                // 发送关闭消息
                                HGPlayer.broadChatMsg(playerId, "双倍掉落活动已结束！", 14);
                                // 清除计时器
                                clearTimeout(warningTimer);
                                clearTimeout(doubleDropTimer);
                                warningTimer = null;
                                doubleDropTimer = null;
                            } catch (error) {
                                console.log('自动关闭双倍掉落失败:', error);
                            }
                        }, 60 * 60 * 1000); // 60分钟后关闭
                    } else {
                        // 如果是关闭双倍掉落，清除计时器
                        if (doubleDropTimer) {
                            clearTimeout(doubleDropTimer);
                            doubleDropTimer = null;
                        }
                        if (warningTimer) {
                            clearTimeout(warningTimer);
                            warningTimer = null;
                        }
                    }
                }
            } catch (error) {
                console.log('双倍掉落设置失败:', error);
            }

            return 1;
        });
    }
}
