function isXinfaStone(stoneId) {
    return st.xinfaList.includes(stoneId);
}

// 检查装备和神秘石是否匹配
function checkMatch(equipId, stoneId) {
    // 武器类型检查
    if (isWeapon(equipId)) {
        return isWeaponStone(stoneId);
    }

    // 帽子和鞋子只能用防具神秘石
    if (isMaoziOrXiezi(equipId)) {
        return isArmorStone(stoneId);
    }

    // 衣服可以用防具神秘石或衣服神秘石
    if (isYifu(equipId)) {
        return isArmorStone(stoneId) || isYifuStone(stoneId);
    }

    // 腰带只能用腰带神秘石
    if (isYaodai(equipId)) {
        return isYaodaiStone(stoneId);
    }

    // 心法只能用心法神秘石
    if (isXinfa(equipId)) {
        return isXinfaStone(stoneId);
    }

    return false;
}

// 获取装备类型描述
function getEquipType(equipId) {
    if (isWeapon(equipId)) return '武器';
    if (eq.maoziList.includes(equipId)) return '帽子';
    if (eq.yifuList.includes(equipId)) return '衣服';
    if (eq.xieziList.includes(equipId)) return '鞋子';
    if (eq.yaodaiList.includes(equipId)) return '腰带';
    if (eq.xingfaList.includes(equipId)) return '心法';
    return '未知装备';
}

// 获取神秘石类型描述
function getStoneType(stoneId) {
    if (isWeaponStone(stoneId)) return '武器神秘石';
    if (isArmorStone(stoneId)) return '防具神秘石';
    if (isYifuStone(stoneId)) return '衣服神秘石';
    if (isYaodaiStone(stoneId)) return '腰带神秘石';
    if (isXinfaStone(stoneId)) return '心法神秘石';
    return '未知神秘石';
}

