//4024	"碎涅·罡·三千界"
class Skill4024Stub extends HSkillStubBase {
    constructor() {
        super(4024);
    }
    attach() {
        // this.hookGetCooldownTimeAfter( (ret, stub, skill)=> {
        //     const hSkill = new HSkill(skill);
        //     const hPlayer = new HPlayerWrapper(hSkill);
        //     return 0;
        // });
        this.hookCalculateReplace(2, (stub, skill) => {
            const hSkill = new HSkill(skill);
            const hPlayer = new HPlayerWrapper(hSkill);

            hSkill.SetRatio(1.1);
            hSkill.SetCrit(0.3);
            let maxMp = hPlayer.GetMaxmp();
            let mpFactor = maxMp * 0.01;
            let skillLevel4573 = hPlayer.GetSkilllevel(4573);
            let var2Value = skillLevel4573 * mpFactor;

            hPlayer.SetVar2(parseInt(var2Value));

            let var1Value = 0;
            if (hPlayer.GetCultivation() == 1 && hPlayer.GetSkilllevel(4573) > 0) {
                var1Value = 120;
            }

            hPlayer.SetVar1(var1Value);

            // 计算星级总和
            let skillLevel6926 = hPlayer.GetSkilllevel(6926);
            let skillLevel6927 = hPlayer.GetSkilllevel(6927);
            let skillLevel6928 = hPlayer.GetSkilllevel(6928);
            let starLevel = skillLevel6926 + skillLevel6927 + skillLevel6928;

            // 计算基础伤害
            let playerLevel = hPlayer.GetLevel();
            let levelFactor = 9 * playerLevel;
            let skillLevelFactor = hSkill.GetLevel() * maxMp / 100;
            let baseDamage = levelFactor + skillLevelFactor;

            // 根据光暗形态调整系数
            let multiplier = 1.0;
            let darklightForm = hPlayer.GetDarklightform();
            if (darklightForm == 4 || darklightForm == 5 || darklightForm == 6) {
                multiplier = hSkill.GetT2() * 0.1 + 1.0;
            }

            // 计算最终伤害加成
            let starBonus = maxMp * (starLevel * 0.01);
            let finalDamage = starBonus + (multiplier * baseDamage);
            let maxhp = hPlayer.GetMaxhp() * 0.3;

            hSkill.SetPlus(finalDamage + maxhp);

            // 调整光暗值
            let darklight = hPlayer.GetDarklight();
            let level = hSkill.GetLevel();
            let t0 = hSkill.GetT0();
            let baseAdjustment = t0 + level;

            let adjustmentDirection = 2;
            if (darklightForm == 5) {
                adjustmentDirection = -2;
            }

            let newDarklight = baseAdjustment * adjustmentDirection + darklight;
            hPlayer.SetDarklight(newDarklight);

            hPlayer.SetPerform(1);
        });
    }
}

