            hSkill.SetCrit(crit);

            // 计算基础加成
            let baseBonus = hSkill.GetLevel() * 0.05 + 0.15;

            // 计算额外加成
            let extraBonus = 0;
            let t2 = hSkill.GetT2();
            let t3 = hSkill.GetT3();
            let t4 = hSkill.GetT4();

            if (t2 >= t3 && t2 >= t4) {
                extraBonus = t2 * 0.012;
            } else if (t3 >= t4) {
                extraBonus = t3 * 0.012;
            } else {
                extraBonus = t4 * 0.012;
            }

            // 计算总伤害倍率
            let t1 = hSkill.GetT1();
            let c0Bonus = hSkill.GetC0() * 0.08 * t1;
            let levelBonus = hSkill.GetLevel() * 0.05 + 1.05;
            let totalRatio = levelBonus + c0Bonus + extraBonus + baseBonus;
            hSkill.SetRatio(totalRatio);

            // 计算附加伤害
            let t0 = hSkill.GetT0();
            let hpBonus = hPlayer.GetHp() * 0.05 * t0;
            let totalPlus = (10 * hSkill.GetLevel() + 244) + hpBonus;
            hSkill.SetPlus(totalPlus);


