            hPlayer.SetTime(t);

            // 直接调用写好的方法设置免疫包裹
            hPlayer.SetImmunewrap(1);

            // 再次调用写好的方法设置概率
            hPlayer.SetProbability(120.0);

            t = (hSkill.GetT2() * 0.1 + 1.0) * 15000.0 + 100.0;
            // 再次调用写好的方法设置时间
            hPlayer.SetTime(t);

            const T0 = hSkill.GetT0();
            let ta = (T0 * hSkill.GetLevel()) * 0.03;
            ta = hSkill.GetLevel() * 0.11 + ta + 0.19;
            // 直接调用写好的方法设置比率
            hPlayer.SetRatio(ta);

            // 直接调用写好的方法设置凝神
            hPlayer.SetNingjin(1);

            // 再次调用写好的方法设置概率
            hPlayer.SetProbability(120.0);

