"use strict";


const HGPlayer = __webpack_require__(1222);

const targetAddr = Module.findExportByName(null, '_ZN18gplayer_dispatcher10cast_skillEiPK3XIDithhsRK9A3DVECTORc');

if (!targetAddr) {
    throw new Error('Target function not found');
}

function parseXID(buffer) {
    const view = new DataView(buffer);
    return {
        id: view.getInt32(4, true)
    };
}

Interceptor.attach(targetAddr, {
    onEnter: function (args) {
        const params = {
            arg4: args[1],                 // char (0Ch)
            xidPtr: args[2],               // XID指针 (10h)
            srcVal: args[3],               // char src (14h) - 技能ID
            arg10: args[4],                // unsigned __int16 (18h)
            arg14: args[5],                // unsigned __int8 (1Ch)
            arg18: args[6],                // unsigned __int8 (20h)
            arg1C: args[7],                // __int16 (24h)
            arg24: args[9]                 // char (2Ch)
        };

        try {
            if (params.xidPtr != 0) {
                console.log(`技能ID=${params.srcVal.toInt32()}      ` +
                          `arg4=${params.arg4.toInt32()}      ` +
                          `arg10=${params.arg10.toInt32()}      ` +
                          `arg14=${params.arg14.toInt32()}      ` +
                          `arg18=${params.arg18.toInt32()}      ` +
                          `arg1C=${params.arg1C.toInt32()}      ` +
                          `arg24=${params.arg24.toInt32()}`);
            }
        } catch (e) {}
    }
});

module.exports = {};

