"use script"

const { HookFuncCore } = __webpack_require__(9452);

/**
 * 钩子模块基类
 * 提供内存操作和模块基址管理功能
 */
class HookModuleBase {
  // 静态属性初始化
  static allModuleBaseIndex = new Map();
  static moduleInitialized = false;

  /**
   * 获取模块基址索引
   * @param {string} moduleName 模块名称
   * @returns {NativePointer} 模块基址
   */
  static getModuleBaseIndex(moduleName) {
    const index = HookModuleBase.allModuleBaseIndex.get(moduleName);
    if (!index) {
      console.error(`无法找到模块 ${moduleName} 的基址索引`);
      return ptr(0);
    }
    return index;
  }

  /**
   * 获取GS模块基址索引
   * @returns {NativePointer} GS模块基址
   */
  static gsBaseIndex() {
    return HookModuleBase.getModuleBaseIndex("gs");
  }

  /**
   * 获取技能模块基址索引
   * @returns {NativePointer} 技能模块基址
   */
  static skillBaseIndex() {
    return HookModuleBase.getModuleBaseIndex("libskill.so");
  }

  /**
   * 通过地址修改内存中的值
   * @param {NativePointer} address 内存地址
   * @param {string} type 值类型，可选 "char"、"int"、"float" 、"double"
   * @param {number} _originValue 原始值（此参数未使用，仅作为参考占位）
   * @param {number} newValue 写入新值
   */
  static modifyValueByAddress(address, type, _originValue, newValue) {
    try {
      Memory.protect(address, 4, "rw-");

      switch (type) {
        case "char": {
          address.writeU8(newValue);
          break;
        }

        case "int": {
          address.writeInt(newValue);
          break;
        }

        case "float": {
          address.writeFloat(newValue);
          break;
        }

        case "double": {
          address.writeDouble(newValue);
          break;
        }

        default: {
          console.log(`错误: 不支持的类型: ${type}`);
          return;
        }
      }
    } catch (e) {
      console.error(`修改值失败: ${e}`);
    }
  }

  /**
   * 读取内存中的值
   * @param {NativePointer} baseIndex 基址
   * @param {number} address 地址
   * @param {string} type 读取的值类型
   * @returns {number|null} 读取的值
   */
  static readOriginValue(baseIndex, address, type) {
    const targetAddress = baseIndex.add(address);

    switch (type) {
      case "char": {
        return targetAddress.readU8();
      }

      case "int": {
        return targetAddress.readInt();
      }

      case "float": {
        return targetAddress.readFloat();
      }

      case "double": {
        return targetAddress.readDouble();
      }

      default: {
        console.log(`错误: 不支持的类型: ${type}`);
        return null;
      }
    }
  }

  /**
   * 通过地址修改技能内存中的值
   * @param {number} address 地址
   * @param {string} type 值类型
   * @param {number} originValue 原始值
   * @param {number} newValue 新值
   */
  static modifySkillValue(address, type, originValue, newValue) {
    // const readOriginValue = HookModuleBase.readOriginValue(
    //   HookModuleBase.skillBaseIndex(),
    //   address,
    //   type,
    // );

    // if (readOriginValue !== null && readOriginValue !== originValue) {
    //   console.log(
    //     `warn: readValue does not match originValue: readValue: ${readOriginValue}, originValue: ${originValue}`,
    //   );
    // }
    try {
      HookModuleBase.modifyValueByAddress(
        HookModuleBase.skillBaseIndex().add(address),
        type,
        originValue,
        newValue,
      );
    } catch (error) {
      console.log(`修改技能值时出错: ${error}`);
    }
  }

  /**
   * 通过地址修改GS内存中的值
   * @param {number} address 地址
   * @param {string} type 值类型
   * @param {number} originValue 原始值
   * @param {number} newValue 新值
   */
  static modifyGSValue(address, type, originValue, newValue) {
    // const readOriginValue = HookModuleBase.readOriginValue(
    //   HookModuleBase.gsBaseIndex(),
    //   address,
    //   type,
    // );

    // if (readOriginValue !== null && readOriginValue !== originValue) {
    //   console.log(
    //     `warn: readValue does not match originValue: readValue: ${readOriginValue}, originValue: ${originValue}`,
    //   );
    // }
    try {
      HookModuleBase.modifyValueByAddress(
        HookModuleBase.gsBaseIndex().add(address),
        type,
        originValue,
        newValue,
      );
    } catch (error) {
      console.log(`修改GS值时出错: ${error}`);
    }
  }

  /**
   * 初始化所有模块基址索引
   * @param {Array<{ name: string; base: NativePointer }>} modules 模块数组
   * @returns {void}
   */
  static initializeModuleBaseIndex(modules) {
    if (!modules || !Array.isArray(modules)) {
      console.log('警告: 模块列表无效');
      return;
    }
    
    try {
      for (const module of modules) {
        if (module && module.name && module.base) {
          HookModuleBase.allModuleBaseIndex.set(module.name, module.base);
          // console.log(`已加载模块: ${module.name} - 基址: ${module.base}`);
        }
      }
      
      // console.log(`共加载 ${HookModuleBase.allModuleBaseIndex.size} 个模块的基址`);
      HookModuleBase.moduleInitialized = true;
    } catch (error) {
      console.error('初始化模块基址失败:', error);
      console.error(error.stack);
    }
  }
}

// 导出模块
module.exports = {
  HookModuleBase
};

