/**
 * 基础钩子技能存根类
 */
class BaseHookSkillStub {
  /**
   * 构造函数
   * @param {number} skillId 技能ID
   */
  constructor(skillId) {
    this.skillId = skillId;
    // 绑定方法到实例
    this.Calculate = this.Calculate.bind(this);
    this.GetCooldowntime = this.GetCooldowntime.bind(this);
  }

  /**
   * 获取技能存根
   * @returns {Stub} 技能存根
   */
  GetStub() {
    return GetStub(this.skillId);
  }

  /**
   * 获取冷却时间钩子
   * @param {Function} callback 回调函数
   */
  GetCooldowntime(callback) {
    if (typeof callback !== 'function') {
      console.error('GetCooldowntime: callback is not a function');
      return;
    }

    const funcName = buildStubFuncName(this.skillId, "GetCooldowntime");
    const funcAddress = HookFuncCore.getFuncAddress("libskill.so", funcName);

    if (!funcAddress) {
      console.error('GetCooldowntime: Unable to find function address');
      return;
    }

    try {
      Interceptor.replace(
        funcAddress,
        new NativeCallback((stubPointer, skillPointer) => {
          const stubImpl = new Stub(stubPointer);
          const skillImpl = new Skill(stubPointer, skillPointer);
          const originFunc = HookFuncCore.getNativeFunc("libskill.so", funcName, "int", ["pointer", "pointer"]);
          return callback(stubImpl, skillImpl, originFunc);
        }, "int", ["pointer", "pointer"])
      );
    } catch (error) {
      console.error('GetCooldowntime hook error:', error);
    }
  }

  /**
   * 计算技能效果钩子
   * @param {Function} callback 回调函数
   */
  Calculate(callback) {
    if (typeof callback !== 'function') {
      console.error('Calculate: callback is not a function');
      return;
    }

    try {
      const size = this.GetStub().GetStateSize();
      // console.log(`skillId: ${this.skillId}, stateSize: ${size}`);

      for (let state = 1; state <= size; state++) {
        const funcName = buildCalculateFuncName(this.skillId, state);
        const funcAddress = HookFuncCore.getFuncAddress("libskill.so", funcName);

        if (!funcAddress) {
          console.error(`Calculate: Unable to find function address for state ${state}`);
          continue;
        }

        Interceptor.replace(
          funcAddress,
          new NativeCallback((stubPointer, skillPointer) => {
            try {
              const stubImpl = new Stub(stubPointer);
              const skillImpl = new Skill(stubPointer, skillPointer);
              const originFunc = HookFuncCore.getNativeFunc("libskill.so", funcName, "void", ["pointer", "pointer"]);
              return callback(stubImpl, skillImpl, originFunc, state);
            } catch (error) {
              console.error(`Calculate callback error for state ${state}:`, error);
              return false;
            }
          }, "void", ["pointer", "pointer"])
        );
      }
    } catch (error) {
      console.error('Calculate hook error:', error);
    }
  }

  /**
   * 获取状态攻击钩子
   * @param {Function} callback 回调函数
   */
  getStateAttack(callback) {
    if (typeof callback !== 'function') {
      console.error('getStateAttack: callback is not a function');
      return;
    }

    try {
      const funcName = buildStubFuncName(this.skillId, "StateAttack");
      const funcAddress = HookFuncCore.getFuncAddress("libskill.so", funcName);

      if (!funcAddress) {
        console.error('getStateAttack: Unable to find function address');
        return;
      }

      Interceptor.replace(
        funcAddress,
        new NativeCallback((stubPointer, skillPointer) => {
          try {
            const stubImpl = new Stub(stubPointer);
            const skillImpl = new Skill(stubPointer, skillPointer);
            const originFunc = HookFuncCore.getNativeFunc("libskill.so", funcName, "int", ["pointer", "pointer"]);
            return callback(stubImpl, skillImpl, originFunc);
          } catch (error) {
            console.error('getStateAttack callback error:', error);
            return 0;
          }
        }, "int", ["pointer", "pointer"])
      );
    } catch (error) {
      console.error('getStateAttack hook error:', error);
    }
  }
}

module.exports = BaseHookSkillStub; 

