//太极玄天真决
class Skill785Stub extends HSkillStubBase {
    constructor() {
        super(785);
    }
    attach() {
        // this.hookGetCooldownTimeAfter( (ret, stub, skill)=> {
        //     return 0;
        // });

        this.hookCalculateAfter(2, (stub, skill) => {
            const hSkill = new HSkill(skill);
            const hPlayer = new HPlayerWrapper(hSkill);
            let mp = hPlayer.GetMp();
            let maxMp = hPlayer.GetMaxmp();
            let ratio = 0.95 - hSkill.GetT2() * 0.1;
            let mpRatio = Number((mp / (maxMp * ratio)).toFixed(2));
            skill785.value = mpRatio;
            // console.log("存===", mpRatio);
        });

        this.hookStateAttackReplace((stub, skill) => {
            const hSkill = new HSkill(skill);
            const hPlayer = new HPlayerWrapper(hSkill);
            let v2 = 5 * hSkill.GetLevel();
            let probability = v2 + 3 * hSkill.GetT1();
            hPlayer.SetProbability(probability);
            hPlayer.SetTime(5100.0);
            hPlayer.SetRatio(0.2);
            hPlayer.SetValue(0.2);
            hPlayer.SetRandcurse(1);
            const mpRatio = skill785.value;
            // console.log("取===", mpRatio);
            if (mpRatio >= 0.95) {
                hPlayer.setIncHurt(120, 6100, 1, 0.02 * hSkill.GetLevel());
            }
            skill785.value = 0;
            return 1;
        });
    }
}
